  if (Fixed !== undefined) {
    const fixed = new Fixed(size);
    counted.pipeTo(fixed.writable).catch(() => {});
    value = fixed.readable;
  }
  return {
    async write<T>(put: (value: ReadableStream<Uint8Array>) => Promise<T>): Promise<T> {
      try {
        return await put(value);
      } catch (e) {
        throw failure ?? e;
      } finally {
        if (!finished) {
          // Not awaited: a read still in flight would hold the put's result.
          finished = true;
          value.cancel().catch(() => {});
          Promise.resolve(iterator.return?.()).catch(() => {});
        }
      }
    },
  };
